"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["9057"],{63700(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.ordem_desempate_duplicada","status":422,"titulo":"Cada crit\xe9rio de desempate deve ter uma ordem \xfanica dentro do processo"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.ordem_desempate_duplicada","requisitos":["UNI-REQ-0015"],"oQueAconteceu":["Dois ou mais crit\xe9rios de desempate na lista declarada repetem o mesmo\\nvalor de `ordem`. A ordem \xe9 o que decide a sequ\xeancia em que os crit\xe9rios\\ns\xe3o aplicados quando um empate persiste depois do primeiro \u2014 repetida, n\xe3o\\nh\xe1 como saber qual crit\xe9rio vem antes.","Na defini\xe7\xe3o, os c\xf3digos dos crit\xe9rios s\xe3o conferidos no `rol_de_regras` antes da ordem. Uma regra inexistente interrompe o processamento antes desta confer\xeancia; depois dela, verifica-se [`etapa_ref_desempate_inexistente`](/erros/uniplus.selecao.processo_seletivo.etapa_ref_desempate_inexistente). A primeira falha interrompe o processamento.","Distinta de\\n[`ordem_invalida`](/erros/uniplus.selecao.criterio_desempate.ordem_invalida),\\nque confere se cada `ordem` individual \xe9 maior que zero. Na defini\xe7\xe3o, essa\\nconfer\xeancia roda numa primeira passada sobre todos os crit\xe9rios do corpo do pedido \u2014\\nantes at\xe9 de o `rol_de_regras` ser consultado \u2014 e acumula todas as\\nviola\xe7\xf5es de ordem de uma vez (ADR-0125) e\\nprecede esta causa, que s\xf3 compara as ordens **entre si**,\\ndepois que cada uma j\xe1 \xe9 sabidamente v\xe1lida isoladamente."],"comoResolver":["Atribua um valor de `ordem` distinto a cada crit\xe9rio de desempate da lista.\\nSe dois crit\xe9rios de fato deveriam ser aplicados no mesmo momento, revise o\\ndesenho do desempate \u2014 o requisito (UNI-REQ-0015) n\xe3o admite ordens\\nsimult\xe2neas."],"ondeAparece":["Defini\xe7\xe3o de crit\xe9rios de desempate do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);